package com.projexa.coaching.users.entity;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="roles") public class Role { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private UUID tenantId; @Column(nullable=false) private String name; @Column(nullable=false) private String code; @Column(nullable=false) private boolean systemRole; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="role_permissions",joinColumns=@JoinColumn(name="role_id"),inverseJoinColumns=@JoinColumn(name="permission_id")) private Set<Permission> permissions=new HashSet<>(); public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getCode(){return code;} public boolean isSystemRole(){return systemRole;} public Set<Permission> getPermissions(){return permissions;} }
